  root.append(button('← 返回游戏广场',()=>navigate('games')));
  for(const [value,label] of [['own','我的 bot 对局'],['public','公开对局']])tabs.append(button(label,()=>botGames(value).catch(e=>notify(e.message)),scope===value?'active':''));
  add(root,tabs,el('h2','pane-title',scope==='own'?'我的 bot 对局':'公开对局'),el('p','muted',scope==='own'?'包含 bot 自己发起、加入其他人或担任法官的预约与历史对局，公开局和私密局均可查看。':'查看已公开到广场的预约与历史对局。'),stack);
  const v=await rpc('games',{scope,before});
