function humanGameText(m){if(m.display)return m.display.body; if(m.gameType==='mystery')return m.text||({started:'剧本杀开局',reminder:'集合报到提醒',closed:'聊天室已关闭',cancelled:'预约已取消'}[m.kind]||'');switch(m.kind){
  case 'left':case 'chat':return m.text||'';
  case 'role':return `你的身份：${roleNames[m.role]||m.role}${m.teammates?.length?`；狼人队友：${m.teammates.join('、')}`:''}`;
  case 'started':return `游戏开始。${Object.entries(m.rules||{}).filter(([,n])=>typeof n==='number'&&n>0).map(([r,n])=>`${roleNames[r]||r} ${n}人`).join(' · ')}`;
  case 'night_wolf':return `第 ${m.day} 夜，狼人选择袭击目标。`;
  case 'night_gods':return `第 ${m.day} 夜，神职行动。请通过下方选项操作。`;
  case 'inspect_result':return `查验结果：${m.target} ${m.isWolf?'是狼人':'不是狼人'}。`;
  case 'witch_prompt':return `本夜狼刀目标：${m.victim||'无'}。解药${m.saveAvailable?'可用':'本夜不可用'}，毒药${m.poisonAvailable?'可用':'已用'}。`;
  case 'dawn':return `第 ${m.day} 天天亮，${m.deaths?.length?`出局：${m.deaths.join('、')}`:'平安夜'}。`;
  case 'day':return `第 ${m.day} 天，公共讨论开始。`;
  case 'vote_open':return `第 ${m.day} 天，公开投票开始。请通过下方选项投票或弃票。`;
  case 'vote':return `${m.voter} ${m.target==='abstain'?'弃票':`投给 ${m.target}`}。`;
  case 'vote_result':return (m.eliminated?`公投出局：${m.eliminated}。`:m.tie?'平票或无人投票，无人出局。':'本轮无人出局。')+(m.votes?`\n投票明细：\n${Object.entries(m.votes).map(([voter,target])=>`${voter} ${target==='abstain'?'弃票':`→ ${target}`}`).join('\n')}`:'');
  case 'attack_vote':return `${m.botId} 选择袭击 ${m.target}`;
  case 'hunter_prompt':return '你可以选择一位存活玩家开枪，也可以放弃。';
  case 'hunter_wait':return `等待猎人 ${m.botId} 行动。`;
  case 'hunter_shot':return `${m.hunter} ${m.target?`开枪带走 ${m.target}`:'放弃开枪'}。`;
  case 'forfeit':return `${m.botId} 弃权出局。`;
  case 'assignments':return `法官身份表：${Object.entries(m.roles||{}).map(([id,r])=>`${id} ${roleNames[r]||r}`).join('；')}`;
  case 'finished':return `游戏结束：${m.winner==='wolves'?'狼人获胜':m.winner==='village'?'好人获胜':'平局'}。\n身份揭晓：\n${Object.entries(m.roles||{}).map(([id,r])=>`${id} · ${roleNames[r]||r}`).join('\n')}\n${m.closeAt?`聊天室关闭时间：${date(m.closeAt)}。`:'2分钟后关闭房间。'}`;
  default:return '游戏状态已更新。';
}}
function renderHumanMessages(root,rows){for(const m of rows)root.append(GameVisual.message(m))}
function gamePhaseKey(g){return [g.gameId,g.status,g.day,g.phaseDeadlineAt].join(':')}
