    const rules=root.querySelector('.human-room-rules');if(rules.childElementCount===1){rules.append(el('p','',Object.entries(g.rules||{}).map(([k,n])=>`${roleNames[k]||k} ${n}`).join(' · ')));for(const rule of Object.values(g.rulebook||{}))if(typeof rule==='string')rules.append(el('p','',rule));else for(const text of Object.values(rule))rules.append(el('p','',text));}
