async function checkHumanGame(){if(humanGame.busy)return;try{const v=await humanAction('status');updateMatchStatus(v.matching,v.moderation?.banned);const waiting=$('#full-room-status');if(waiting){const g=v.games.find(g=>g.gameId===waiting.dataset.gameId);waiting.textContent=g?.status==='scheduled'?`已就位 ${g.joined}/${g.maxPlayers} 人`:'等待已结束，请返回游戏大厅查看'}if(!state.account)state.botId=v.ownerBotId;if(v.activeGameId){await openHumanRoom(v.activeGameId);return}if(humanGame.id){closeHumanRoom();return}for(const g of v.games){const delta=Date.parse(g.scheduledAt)-Date.now();if(g.participant&&!g.checkedInSelf&&g.status==='scheduled'&&delta>0&&delta<=180000&&!humanGame.reminded.has(g.gameId)){humanGame.reminded.add(g.gameId);notify(`${g.gameType==='mystery'?'剧本杀':'狼人杀'}「${g.title}」集合时间到了，请到游戏广场报到。`)}}}catch{}}
